#[derive(Debug, thiserror::Error)]
pub enum ReadError {
    #[error("reading input: {0}")]
    Io(#[from] std::io::Error),
    #[error("parsing record count: {0}")]
    Count(#[from] std::num::ParseIntError),
    #[error("decoding input text: {0}")]
    Utf8(#[from] std::str::Utf8Error),
    #[error("measuring elapsed time: {0}")]
    Clock(#[from] std::time::SystemTimeError),
}
pub fn read_count(path: &std::path::Path) -> Result<u32, ReadError> {
    let bytes = std::fs::read(path)?;
    let text = std::str::from_utf8(&bytes)?;
    Ok(text.trim().parse()?)
}
pub fn elapsed(since: std::time::SystemTime) -> Result<std::time::Duration, ReadError> {
    Ok(since.elapsed()?)
}

#[derive(Debug, thiserror::Error)]
pub enum LoadError {
    #[error("configuration I/O: {0}")]
    Io(#[from] std::io::Error),
}
pub fn load(primary: &std::path::Path, fallback: &std::path::Path) -> Result<(String, String), LoadError> {
    let first = std::fs::read_to_string(primary)?;
    let second = std::fs::read_to_string(fallback)?;
    Ok((first, second))
}
pub fn run(primary: &std::path::Path, fallback: &std::path::Path) {
    match load(primary, fallback) {
        Ok((a, b)) => println!("loaded {} bytes", a.len() + b.len()),
        Err(error) => eprintln!("{error}"),
    }
}

pub fn persist(path: &std::path::Path, bytes: &[u8]) -> std::io::Result<()> {
    std::fs::write(path, bytes).ok();
    Ok(())
}

pub fn timeout(raw: Option<&str>) -> u64 {
    raw.and_then(|value| value.parse().ok()).unwrap_or(30)
}

